from django import template
from django.template.base import token_kwargs
from djinn.core.cva import cva

register = template.Library()

data_table_cva = cva(
    base="rounded-md border bg-card text-card-foreground shadow-sm",
    variants={},
    default_variants={}
)

class DataTableNode(template.Node):
    def __init__(self, nodelist, kwargs):
        self.nodelist = nodelist
        self.kwargs = kwargs

    def render(self, context):
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            try:
                resolved_kwargs[k] = v.resolve(context)
            except template.VariableDoesNotExist:
                resolved_kwargs[k] = ""

        final_class = data_table_cva(**resolved_kwargs)

        known_args = ["caption", "thead", "tbody", "actions", "class", "class_name"]
        attrs = {k: v for k, v in resolved_kwargs.items() if k not in known_args}

        t = context.template.engine.get_template('components/data-table.html')
        new_context = context.new({
            "class": final_class,
            "attrs": attrs,
            **resolved_kwargs
        })
        return t.render(new_context)

@register.tag('djinn_data_table')
def djinn_data_table(parser, token):
    bits = token.split_contents()
    kwargs = token_kwargs(bits[1:], parser)
    nodelist = parser.parse(('enddjinn_data_table',))
    parser.delete_first_token()
    return DataTableNode(nodelist, kwargs)
